import subprocess, struct, itertools
base = bytearray(open('valid.jpc','rb').read())
def run(name, data, to=5):
    open('m.jpc','wb').write(bytes(data))
    try:
        p = subprocess.run(['/workspace/artifacts/target/jasper','-f','m.jpc','-t','jpc','-F','/dev/null','-T','pnm'],
                           capture_output=True, timeout=to)
        if p.returncode < 0:
            print(f"CRASH {name}: rc={p.returncode} stderr={p.stderr.decode(errors='replace')[:200]!r}")
    except subprocess.TimeoutExpired:
        print(f"HANG {name}")

def set32(d, off, v): d[off:off+4] = struct.pack('>I', v & 0xffffffff)
def set16(d, off, v): d[off:off+2] = struct.pack('>H', v & 0xffff)

# SIZ fields: Xsiz@8 Ysiz@12 XOsiz@16 YOsiz@20 XTsiz@24 YTsiz@28 XTOsiz@32 YTOsiz@36 Csiz@40
vals = [0,1,2,3,5,16,17,255,256,0x7fff,0x8000,0xffff,0x10000,0x7fffffff,0x80000000,0xfffffffe,0xffffffff]
fields = {'Xsiz':8,'Ysiz':12,'XOsiz':16,'YOsiz':20,'XTsiz':24,'YTsiz':28,'XTOsiz':32,'YTOsiz':36}
for fname, off in fields.items():
    for v in vals:
        d = bytearray(base); set32(d, off, v)
        run(f"{fname}={v:#x}", d, to=3)
# COD numlvls @ 0x5e? COD at 0x54: ff52 000c 00 00 0001 00 05 04 04 00 01 -> Scod@0x58=00 Prog@0x59=00 Layers@0x5a=0001 MCT@0x5c=00 Lvls@0x5d=05
for v in [0,1,2,10,32,33,64,255]:
    d = bytearray(base); d[0x5d]=v
    run(f"numlvls={v}", d, to=3)
# codeblock w/h @0x5e,0x5f (stored as exp-2)
for v in [0,1,11,12,255]:
    for off,nm in [(0x5e,'cbw'),(0x5f,'cbh')]:
        d = bytearray(base); d[off]=v
        run(f"{nm}={v}", d, to=3)
print("done")
